input.command:
mkdir -p .perfproof/harness .perfproof/specs && cat > .perfproof/harness/zz_pf_bench_test.go <<'EOF'
package echo

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
	"testing"
)

type pfBody struct{ r *strings.Reader }

func (n pfBody) Read(p []byte) (int, error) { return n.r.Read(p) }
func (pfBody) Close() error                 { return nil }

type pfWriter struct{ h http.Header }

func (w *pfWriter) Header() http.Header {
	if w.h == nil {
		w.h = make(http.Header)
	}
	return w.h
}
func (w *pfWriter) Write(b []byte) (int, error) { return len(b), nil }
func (w *pfWriter) WriteHeader(int)             {}

type pfTarget struct {
	ID     int    `json:"id" query:"id"`
	Name   string `json:"name" query:"name"`
	Email  string `json:"email" query:"email"`
	Age    int    `json:"age" query:"age"`
	Active bool   `json:"active" query:"active"`
}

func BenchmarkPFBindJSON(b *testing.B) {
	e := New()
	body := `{"id":1,"name":"Jon Snow","email":"jon@winterfell.north","age":24,"active":true}`
	var last pfTarget
	e.POST("/", func(c *Context) error {
		var t pfTarget
		err := c.Bind(&t)
		last = t
		return err
	})
	r := strings.NewReader(body)
	req := httptest.NewRequest(http.MethodPost, "/", r)
	req.Header.Set(HeaderContentType, MIMEApplicationJSON)
	req.Body = pfBody{r}
	w := &pfWriter{}
	b.ReportAllocs()
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		w.h = nil
		r.Reset(body)
		e.ServeHTTP(w, req)
	}
	b.StopTimer()
	if last != (pfTarget{1, "Jon Snow", "jon@winterfell.north", 24, true}) {
		b.Fatalf("wrong bind result %+v", last)
	}
	os.MkdirAll("out", 0o755)
	os.WriteFile("out/result.txt", []byte(fmt.Sprintf("%+v\n", last)), 0o644)
}
EOF
cat > .perfproof/specs/pf_bind_json.json <<'EOF'
{
  "schema_version": 4,
  "name": "pf_bind_json",
  "command": ["bin/echo.test", "-test.run", "^$", "-test.bench", "^BenchmarkPFBindJSON$", "-test.benchtime", "600000x", "-test.count", "1"],
  "cwd": ".",
  "env": {},
  "setup": {"commands": [["go", "mod", "download"],
                         ["cp", ".perfproof/harness/zz_pf_bench_test.go", "zz_pf_bench_test.go"],
                         ["go", "test", "-c", "-o", "bin/echo.test", "."]],
            "timeout_seconds": 900},
  "metric": {"kind": "wall", "direction": "lower_is_better", "unit": "s"},
  "objective": "wall_time",
  "guardrails": [
    {"metric": "peak_memory", "direction": "lower_is_better", "unit": "bytes", "allowance": 0.1, "allowance_source": "default"},
    {"metric": "peak_gpu_memory", "direction": "lower_is_better", "unit": "bytes", "applicable": false, "reason": "no GPU is used"},
    {"metric": "p99_latency", "direction": "lower_is_better", "unit": "s", "applicable": false, "reason": "serves no requests over a network"}
  ],
  "correctness": {
    "command": ["go", "test", ".", "-run", "Bind|JSON"],
    "cwd": ".",
    "timeout_seconds": 300,
    "outputs": [{"path": "out/result.txt", "compare": "text"}]
  },
  "warmup": 1,
  "budget": {"max_rounds": 60, "max_seconds": 1800},
  "looks": {"n0": 10, "k": 10, "max_looks": 6},
  "min_effect": 0.03,
  "alpha": 0.05,
  "timeout_seconds": 120,
  "harness": [".perfproof/harness/zz_pf_bench_test.go"],
  "oracle": [],
  "inputs": [],
  "config": [],
  "allow_runtime_change": false,
  "allow_cross_host": false
}
EOF
perfproof bench define pf_bind_json --spec .perfproof/specs/pf_bind_json.json --json | head -30

